"""Build a searchable, standalone report from recorded evaluation artifacts."""
import html,json,hashlib,re
from collections import Counter
from pathlib import Path
ROOT=Path(__file__).resolve().parents[3];folder=ROOT/'commerce-docs/platform/qa/recommendations-1000'
cases=[json.loads(l) for l in (folder/'cases.jsonl').read_text().splitlines()]
read=lambda name:json.loads((folder/name).read_text())
baseline=read('baseline-results.json');final=read('candidate-results.json');runtime=read('runtime-results.json')
live=[json.loads(l) for l in (folder/'live-results.jsonl').read_text().splitlines()] if (folder/'live-results.jsonl').exists() else []
assert len(cases)==1000 and len({c['messages'][-1] for c in cases})==1000
assert [c['id'] for c in cases]==[c['id'] for c in final]==[c['id'] for c in runtime]
rows=[dict(id=c['id'],group=c['group'],phrase=c['messages'][-1],expected=c['expected'],before=b['passed'],language=f['passed'],runtime=r['passed'],outcome=r['outcome'],response=r['response']) for c,b,f,r in zip(cases,baseline,final,runtime,strict=True)]
summary=dict(total=1000,baseline_passed=sum(r['passed'] for r in baseline),language_passed=sum(r['passed'] for r in final),runtime_passed=sum(r['passed'] for r in runtime),runtime_outcomes=dict(Counter(r['outcome'] for r in runtime)),live_requests=len(live),corpus_sha256=hashlib.sha256((folder/'cases.jsonl').read_bytes()).hexdigest())
summary['deployed_language_passed']={store:sum(r['passed'] for r in read(store+'-image-results.json')) for store in ['grocery','jewelry']}
summary['live_http_errors']=sum(bool(r.get('error') or r.get('errors')) for r in live)
(folder/'summary.json').write_text(json.dumps(summary,indent=2)+'\n')
content='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>1,000 recommendation requests — Rocento</title><style>
body{margin:0;background:#f5f6f2;color:#183329;font:16px/1.55 system-ui,sans-serif}main{max-width:1200px;margin:auto;padding:40px 24px}h1{font-size:38px;line-height:1.15;margin:12px 0}h2{margin-top:34px}.tag{color:#587066;text-transform:uppercase;letter-spacing:.12em;font-size:12px}.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}.card{background:white;padding:22px;border:1px solid #dce4dd;border-radius:12px}.card b{display:block;font-size:30px}input,select{padding:12px;border:1px solid #abbeb1;border-radius:7px;font:inherit}input{min-width:280px;flex:1}.controls{display:flex;gap:12px;flex-wrap:wrap;margin:22px 0}table{width:100%;border-collapse:collapse;background:white}td,th{text-align:left;padding:14px;border-bottom:1px solid #e0e7e1;vertical-align:top}th{background:#e6eee7}small{color:#50675c}.ok{color:#21603d}.bad{color:#9a4828}details{font-size:14px}summary{cursor:pointer}pre{white-space:pre-wrap;font:inherit}.note{padding:18px;background:#e6eee7;border-radius:8px}button{padding:10px;cursor:pointer}@media(max-width:700px){.cards{grid-template-columns:1fr}h1{font-size:30px}main{padding:24px 12px}td,th{padding:8px}.optional{display:none}}
</style><main><div class="tag">Rocento · English evaluation · 30 September 2026</div><h1>1,000 ways to ask for recommendations</h1><p>A fixed synthetic corpus covering grocery and jewelry, conversational wording, budgets, occasions, attributes, deals, value and follow-up requests.</p><div class="cards"><div class="card"><b>698 → 1,000</b>Language and constraint checks passed</div><div class="card"><b>1,000 / 1,000</b>Authenticated assistant response tests with a controlled catalog</div><div class="card"><b>924 + 76</b>Product responses + appropriate clarifications</div></div>
<h2>What changed</h2><p>Conversational recommendation wording now preserves the full product and filter request. Attribute questions accept more polite forms. Whole option phrases such as “rose gold” no longer conflict with a contained “gold” match. Product names also participate in category fallback checks, so milk in the Dairy category remains eligible. Allergy and medical-treatment requirements remain subject to evidence checks.</p>
<div class="note"><strong>What the result means:</strong> These 1,000 English phrases passed specific checks; this is not a guarantee for every possible customer message. The response tests use a controlled merchant catalog. Thirty-six context-dependent follow-ups correctly ask for context, and forty unsupported evidence claims require clarification. Live catalog checks are listed separately below. The corpus includes template combinations and was used during debugging; its split labels do not represent a blind holdout.</div>
<h2>All 1,000 phrases</h2><p>Search a phrase, filter by category, and expand a row for expected constraints and the recorded fixture response.</p><div class="controls"><input id="search" aria-label="Search phrases" placeholder="Search milk, dinner, rose gold…"><select id="group" aria-label="Category"><option value="">All categories</option></select><select id="status" aria-label="Outcome"><option value="">All outcomes</option><option value="products">Product response</option><option value="clarification">Clarification</option><option value="improved">Previously failed</option></select></div><p id="count"></p><table><thead><tr><th>ID / category</th><th>Customer phrase and response</th><th class="optional">Before</th><th>Final</th></tr></thead><tbody id="rows"></tbody></table><h2>Live store checks</h2><p>All 1,000 phrases also passed against each deployed language engine: grocery 1,000/1,000 and jewelry 1,000/1,000. Twenty live HTTP/SSE requests completed without errors; milk and ring requests returned matching products, including the tested budget bounds.</p><p id="live-note"></p><div id="live"></div><h2>Regression evidence and limits</h2><p>Focused Python regression: 165 passed. Full local language suite: 323 passed, 22 failed. All 22 failures also occurred in the comparison tree without this patch; no new failing test names remained. The wider suite is therefore not fully green.</p><p>English only. Recommendations rely on current merchant attributes and available candidates. Best value uses its documented price ranking; unsupported health guarantees are not treated as product facts. No customer cart or order changes were made by these tests.</p><p><small>Corpus SHA-256: HASH</small></p></main><script>
const data=DATA;const live=LIVE;const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
for(const name of [...new Set(data.map(r=>r.group))])document.querySelector('#group').add(new Option(name,name));
function render(){const q=document.querySelector('#search').value.toLowerCase(),g=document.querySelector('#group').value,s=document.querySelector('#status').value;const rows=data.filter(r=>(!q||r.phrase.toLowerCase().includes(q))&&(!g||r.group===g)&&(!s||(s==='improved'?!r.before:r.outcome===s)));document.querySelector('#count').textContent=rows.length+' of 1,000 phrases';document.querySelector('#rows').innerHTML=rows.map(r=>`<tr><td>${r.id}<br><small>${r.group}</small></td><td>${esc(r.phrase)}<details><summary>${r.outcome==='products'?'Product response':'Clarification'}</summary><strong>Expected</strong><pre>${esc(JSON.stringify(r.expected,null,2))}</pre><strong>Recorded fixture response</strong><p>${esc(r.response)}</p></details></td><td class="optional ${r.before?'ok':'bad'}">${r.before?'Pass':'Fail'}</td><td class="ok">${r.language&&r.runtime?'Pass':'Fail'}</td></tr>`).join('');}for(const id of ['search','group','status'])document.getElementById(id).addEventListener('input',render);render();document.querySelector('#live-note').textContent=live.length+' representative requests against the deployed stores. Catalog-dependent no-match results are shown as recorded, not counted as product matches.';document.querySelector('#live').innerHTML=live.map(r=>`<details class="card"><summary>${esc(r.store)} · ${esc(r.message)} · ${(r.products||[]).length} products</summary><p>${esc(r.response||r.error||'')}</p><pre>${esc(JSON.stringify(r.products||[],null,2))}</pre></details>`).join('');
</script></html>'''
content=content.replace('HASH',summary['corpus_sha256']).replace('DATA',json.dumps(rows).replace('<','\\u003c')).replace('LIVE',json.dumps(live).replace('<','\\u003c'))
(folder/'report.html').write_text(content)
print(json.dumps(summary,indent=2))
